import { html, render } from 'lit';
import '@tweakpad/ui/register';
import '@tweakpad/ui/styles.css';
import { boldIcon, italicIcon, underlineIcon } from '@tweakpad/ui/icons/text-formatting';

const items = [
  { type: 'group', label: 'Formatting', items: [
    { value: 'bold', text: 'Bold', label: html`<tp-icon size="var(--tp-icon-size-sm)" .icon=${boldIcon}></tp-icon>Bold` },
    { value: 'italic', text: 'Italic', label: html`<tp-icon size="var(--tp-icon-size-sm)" .icon=${italicIcon}></tp-icon>Italic` },
  ] },
  { type: 'separator' },
  { type: 'group', label: 'Decoration', items: [
    { value: 'underline', text: 'Underline', label: html`<tp-icon size="var(--tp-icon-size-sm)" .icon=${underlineIcon}></tp-icon>Underline <tp-badge variant="secondary">New</tp-badge>` },
  ] },
];
render(html`<tp-select label="Text style" placeholder="Choose a style" .items=${items}></tp-select>`, document.body);

import '@tweakpad/ui/register';
import '@tweakpad/ui/styles.css';
const select = document.createElement('tp-select');
select.label = 'Country';
select.placeholder = 'Choose a country';
select.items = Array.from({ length: 100 }, (_, index) => ({
  value: `country-${index + 1}`, label: `Country ${index + 1}`,
}));
document.body.append(select);
